import PyPDF2, os, re, json

def extract_text(pdf_path):
    try:
        reader = PyPDF2.PdfReader(pdf_path)
        # Get first page text - enough for title
        text = ""
        for i in range(min(2, len(reader.pages))):
            try:
                text += reader.pages[i].extract_text() or ""
            except:
                pass
        return text
    except Exception as e:
        return f"ERROR: {e}"

results = {}
for f in sorted(os.listdir('.')):
    if not f.endswith('.pdf'):
        continue
    text = extract_text(f)
    # First chunk is title (after arXiv marker)
    # Get rid of arXiv line
    text_clean = re.sub(r'arXiv:\S+', '', text)
    text_clean = re.sub(r'\s+', ' ', text_clean)
    # Take first 600 chars
    results[f] = text_clean[:800].strip()

# Print all titles
for f, t in results.items():
    print(f"--- {f} ---")
    print(t[:400])
    print()
EOF

